from oeplatform.settings import PSEUDO_TOPIC_DRAFT


def backfill_topics_from_member_tables(apps, schema_editor):
    """Seed every existing dataset with its member tables' topics, mirroring
    the additive seeding that now happens on assign. The draft pseudo-topic
    is never a dataset topic."""
    Dataset = apps.get_model("dataedit", "Dataset")
    for dataset in Dataset.objects.prefetch_related("tables__topics"):
        topic_names = {
            topic.name
            for table in dataset.tables.all()
            for topic in table.topics.all()
            if topic.name != PSEUDO_TOPIC_DRAFT
        }
        if topic_names:
            dataset.topics.add(*topic_names)


